<script setup lang="ts">
import { ref, watch } from 'vue'
import { orderKinds, centsFromInput } from '../domain.js'
import { request } from '../api'
const props=defineProps<{kind:string;modelValue?:string;disabled?:boolean}>()
const emit=defineEmits<{'update:modelValue':[value:string];busy:[value:boolean]}>()
const rows=ref<any[]>([]),selected=ref<string[]>([])
const rewardNames:Record<string,string>={badge:'徽章',growth:'成长值',coupon:'优惠券',maintenance_coupon:'维修养护券',physical_gift:'实物礼包',event_invitation:'活动邀请资格'}
const uploadError=ref(''),uploading=ref(false)
watch(()=>props.modelValue,value=>{try{const parsed=value?JSON.parse(value):['parameters','before_parameters','after_parameters'].includes(props.kind)?{}:[];if(['parameters','before_parameters','after_parameters'].includes(props.kind))rows.value=Object.entries(parsed).map(([key,value])=>({key,value}));else if(['image_urls','joint_merchant_codes'].includes(props.kind))rows.value=parsed.map((value:string)=>({value}));else if(props.kind==='order_types')selected.value=parsed;else if(props.kind==='options')rows.value=parsed.map((row:any)=>({...row,price_input:(Number(row.price_cents)/100).toFixed(2)}));else rows.value=parsed}catch{rows.value=[]}}, {immediate:true})
function changed(){try{const value=['parameters','before_parameters','after_parameters'].includes(props.kind)?Object.fromEntries(rows.value.filter(row=>row.key).map(row=>[row.key,row.value])):['image_urls','joint_merchant_codes'].includes(props.kind)?rows.value.map(row=>row.value).filter(Boolean):props.kind==='order_types'?selected.value:props.kind==='options'?rows.value.map(({id,title,price_input})=>({id,title,price_cents:price_input?centsFromInput(price_input):0})):rows.value;emit('update:modelValue',JSON.stringify(value));uploadError.value=''}catch(err){uploadError.value=(err as Error).message}}
function add(){rows.value.push(props.kind==='lessons'?{id:crypto.randomUUID(),title:'',video_url:'',duration_seconds:''}:props.kind==='options'?{id:crypto.randomUUID(),title:'',price_input:'0.00'}:props.kind==='rewards'?{id:crypto.randomUUID(),type:'badge',title:'',points:1,coupon_id:'',event_id:''}:props.kind==='questions'?{question:'',options:['',''],answer:0}:['parameters','before_parameters','after_parameters'].includes(props.kind)?{key:'',value:''}:{value:''})}
function remove(index:number){rows.value.splice(index,1);changed()}
async function uploadVideo(event:Event,row:any){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;uploadError.value='';if(file.type!=='video/mp4'||file.size>50*1024*1024){uploadError.value='请选择不超过50MB的MP4视频';return}uploading.value=true;emit('busy',true);let url='';try{url=URL.createObjectURL(file);const video=document.createElement('video');video.preload='metadata';const duration=await new Promise<number>((resolve,reject)=>{video.onloadedmetadata=()=>resolve(Math.ceil(video.duration));video.onerror=()=>reject(new Error('无法读取视频时长，请确认MP4文件可播放'));video.src=url});if(!Number.isFinite(duration)||duration<1||duration>86400)throw new Error('视频时长须在1秒至24小时之间');const body=new FormData();body.append('file',file);body.append('private','0');const result=await request<{url:string}>('/uploads',{method:'POST',body});if(!result.url)throw new Error('服务未返回可用视频地址');const target=rows.value.find(item=>item.id===row.id)||row;target.video_url=result.url;target.duration_seconds=duration;changed()}catch(err){uploadError.value=(err as Error).message}finally{if(url)URL.revokeObjectURL(url);uploading.value=false;emit('busy',false)}}
</script>
<template>
  <div class="structured-field"><p v-if="uploadError" class="notice danger" role="alert">{{ uploadError }}</p><template v-if="kind==='order_types'"><div class="checkbox-grid"><label v-for="(name,key) in orderKinds" :key="key"><input v-model="selected" type="checkbox" :value="key" @change="changed" /><span>{{ name }}</span></label></div></template><template v-else><div v-for="(row,index) in rows" :key="row.id||index" class="structured-row"><div class="structured-row-title"><strong>{{ kind==='lessons'?`章节 ${index+1}`:kind==='questions'?`题目 ${index+1}`:kind==='options'?`配置 ${index+1}`:kind==='joint_merchant_codes'?`参与商家 ${index+1}`:kind==='rewards'?`奖励 ${index+1}`:kind==='parameters'?`参数 ${index+1}`:`图片 ${index+1}` }}</strong><button type="button" class="text-button danger-text" @click="remove(index)">移除</button></div><template v-if="kind==='lessons'"><input v-model="row.title" placeholder="章节标题" aria-label="章节标题" @change="changed" /><input v-model="row.video_url" type="text" inputmode="url" placeholder="学习视频 HTTPS 地址或已上传视频" aria-label="学习视频地址" @change="changed" /><label><span>{{ uploading?'正在上传视频…':'上传学习视频（MP4，最多50MB）' }}</span><input type="file" accept="video/mp4" :disabled="disabled||uploading" aria-label="上传学习视频" @change="uploadVideo($event,row)" /></label><label><span>视频总时长（秒） *</span><input v-model.number="row.duration_seconds" type="number" min="1" max="86400" placeholder="请输入视频实际时长" required @change="changed" /></label></template><template v-else-if="kind==='questions'"><textarea v-model="row.question" rows="2" placeholder="题目内容" aria-label="题目内容" @change="changed" /><div v-for="(_,option) in row.options" :key="option" class="quiz-option"><input v-model="row.options[option]" :placeholder="`选项 ${Number(option)+1}`" :aria-label="`选项 ${Number(option)+1}`" @change="changed" /><button type="button" class="text-button" :disabled="row.options.length<=2" @click="row.options.splice(option,1);changed()">移除</button></div><button type="button" class="text-button" @click="row.options.push('');changed()">＋ 增加选项</button><label><span>正确答案</span><select v-model.number="row.answer" @change="changed"><option v-for="(_,option) in row.options" :key="option" :value="Number(option)">选项 {{ Number(option)+1 }}</option></select></label></template><template v-else-if="kind==='options'"><label><span>配置名称 *</span><input v-model="row.title" aria-label="配置名称" required @change="changed" /></label><label><span>附加价格（元） *</span><input v-model="row.price_input" inputmode="decimal" pattern="[0-9]+(\.[0-9]{1,2})?" required @change="changed" /></label></template><template v-else-if="kind==='joint_merchant_codes'"><input v-model="row.value" aria-label="参与商家统一社会信用代码" placeholder="18位统一社会信用代码" pattern="[0-9A-HJ-NP-RTUWXY]{18}" required @change="changed" /></template><template v-else-if="kind==='rewards'"><label><span>奖励类型</span><select v-model="row.type" aria-label="奖励类型" @change="changed"><option v-for="(label,key) in rewardNames" :key="key" :value="key">{{ label }}</option></select></label><label><span>奖励名称 *</span><input v-model="row.title" required aria-label="奖励名称" placeholder="例如安全航行徽章" @change="changed" /></label><label v-if="row.type==='growth'"><span>成长值 *</span><input v-model.number="row.points" type="number" min="1" max="10000" required @change="changed" /></label><label v-if="['coupon','maintenance_coupon'].includes(row.type)"><span>已发布优惠券 ID *</span><input v-model.number="row.coupon_id" type="number" min="1" required @change="changed" /><small v-if="row.type==='maintenance_coupon'">优惠券须适用于维修养护订单。</small></label><label v-if="row.type==='event_invitation'"><span>已发布活动 ID *</span><input v-model.number="row.event_id" type="number" min="1" required @change="changed" /><small>发放报名资格，用户仍须主动报名。</small></label><p v-if="row.type==='physical_gift'" class="muted">完成课程后生成待发放记录，由平台填写实物交付凭据。</p><small>已发放奖励不可改变类型及权益；新增奖励请另添加一项。</small></template><template v-else-if="kind==='parameters'"><div class="recipient-row"><input v-model="row.key" placeholder="参数名称，例如动力" aria-label="参数名称" @change="changed" /><input v-model="row.value" placeholder="参数值，例如500HP" aria-label="参数值" @change="changed" /></div></template><template v-else><input v-model="row.value" type="text" inputmode="url" placeholder="图片 HTTPS 地址或已上传图片" aria-label="图片地址" @change="changed" /></template></div><button type="button" class="button small" @click="add">＋ {{ kind==='lessons'?'添加章节':kind==='questions'?'添加题目':kind==='rewards'?'添加奖励':kind==='options'?'添加配置':kind==='joint_merchant_codes'?'添加参与商家':kind==='parameters'?'添加参数':'添加图片地址' }}</button></template></div>
</template>
